package initcmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func renderGitIgnore() string {
	return ".agent/*\ndata/*\n"
}

func renderReadme(options Options) string {
	return fmt.Sprintf(
		"# %s\n\nGenerated by `kumacore`.\n\n## Modules\n\n%s\n\n## Start\n\n1. Run `go run ./cmd/server`.\n2. Open `http://127.0.0.1:3000`.\n\nRuntime files are written under `data/`.\n",
		options.ProjectName,
		renderReadmeModules(options.Modules),
	)
}

func renderReadmeModules(moduleIDs []string) string {
	selectedModules := normalizeModuleIDs(moduleIDs)
	if len(selectedModules) == 0 {
		return "- none"
	}

	lines := make([]string, 0, len(selectedModules))
	for _, moduleID := range selectedModules {
		lines = append(lines, "- "+moduleID)
	}

	return strings.Join(lines, "\n")
}

// renderAppEmbed builds app/embed.go for the selected modules.
//
// Every go:embed pattern must match at least one file. Modules without page templates, such as health, contribute no
// pattern so a selection with no HTML pages still compiles.
func renderAppEmbed(moduleIDs []string, projectName string) ([]byte, error) {
	patterns := []string{
		"web/templates/layouts/*.html",
		"web/templates/components/*.html",
	}

	for _, moduleID := range normalizeModuleIDs(moduleIDs) {
		hasPageTemplates, err := moduleHasPageTemplates(moduleID)
		if err != nil {
			return nil, err
		}

		if !hasPageTemplates {
			continue
		}

		patterns = append(patterns, fmt.Sprintf("modules/%s/*.html", moduleID))
	}

	return []byte(fmt.Sprintf(`// Package app is the top-level application package for %s.
package app

import "embed"

// Templates holds all templates baked into the binary at compile time: shared layouts, shared components, each module's
// page templates, and per-module component fragments (modules/<name>/components/*.html).
//
//go:embed %s
var Templates embed.FS
`, projectName, strings.Join(patterns, " "))), nil
}

func moduleHasPageTemplates(moduleID string) (bool, error) {
	moduleDirectory := filepath.Join("app", "modules", moduleID)

	directoryEntries, err := os.ReadDir(moduleDirectory)
	if err != nil {
		return false, fmt.Errorf("[initcmd:moduleHasPageTemplates] read %s: %w", moduleDirectory, err)
	}

	for _, directoryEntry := range directoryEntries {
		if directoryEntry.IsDir() {
			continue
		}

		if strings.HasSuffix(directoryEntry.Name(), ".html") {
			return true, nil
		}
	}

	return false, nil
}

func renderJobImports(metadata RepoMetadata) string {
	return joinSectionLines([]string{
		`	jobslogging "kumacore/app/jobs/logging"`,
		`	"kumacore/app/jobs/backup"`,
	})
}

func renderModuleImports(metadata RepoMetadata) string {
	moduleImports := make([]string, 0, len(metadata.Modules))
	for _, moduleSelection := range metadata.Modules {
		switch moduleSelection.ID {
		case "home":
			moduleImports = append(moduleImports, `	"kumacore/app/modules/home"`)
		case "auth":
			moduleImports = append(moduleImports,
				`	authmiddleware "kumacore/app/middleware/auth"`,
				`	authmodule "kumacore/app/modules/auth"`,
				`	authrepository "kumacore/app/repositories/auth"`,
				`	authservice "kumacore/app/services/auth"`,
				`	"kumacore/core/cache"`,
			)
		case "health":
			moduleImports = append(moduleImports, `	healthmodule "kumacore/app/modules/health"`)
		}
	}

	return joinSectionLines(moduleImports)
}

func renderModuleSetup(metadata RepoMetadata) string {
	setupLines := make([]string, 0, len(metadata.Modules))
	for _, moduleSelection := range metadata.Modules {
		switch moduleSelection.ID {
		case "home":
			setupLines = append(setupLines, `	homeHandler := home.NewHandler(renderer, configuration.App.Name)`)
		case "auth":
			setupLines = append(
				setupLines,
				`	authRepository := authrepository.NewRepository(appDatabase)`,
				`	userCache := cache.NewCache[string, authservice.CachedUser](configuration.Core.Session.CacheTTL)`,
				`	authService, err := authservice.NewService(authRepository, configuration.Core.Session.TTL, userCache)`,
				`	if err != nil {`,
				`		return moduleBootstrap{}, err`,
				`	}`,
				`	authHandler := authmodule.NewHandler(renderer, authService, configuration.Core.App.Dev)`,
			)
		case "health":
			setupLines = append(setupLines,
				`	healthHandler := healthmodule.NewHandler(`,
				`		appDatabase,`,
				`		appDialect,`,
				`		newAppMigrationSource(),`,
				`	)`,
			)
		}
	}

	return joinSectionLines(setupLines)
}

func renderModuleMiddleware(metadata RepoMetadata) string {
	middlewareLines := make([]string, 0, len(metadata.Modules))
	for _, moduleSelection := range metadata.Modules {
		if moduleSelection.ID == "auth" {
			middlewareLines = append(middlewareLines, `			authmiddleware.LoadAuth(authService),`)
		}
	}

	return joinSectionLines(middlewareLines)
}

func renderModuleRoutes(metadata RepoMetadata) string {
	routeLines := make([]string, 0, len(metadata.Modules))
	for _, moduleSelection := range metadata.Modules {
		switch moduleSelection.ID {
		case "home":
			routeLines = append(routeLines, `			home.Routes(homeHandler),`)
		case "auth":
			routeLines = append(routeLines, `			authmodule.Routes(authHandler),`)
		case "health":
			routeLines = append(routeLines, `			healthmodule.Routes(healthHandler),`)
		}
	}

	return joinSectionLines(routeLines)
}

func renderJobRegistrations() string {
	return joinSectionLines([]string{
		`			{`,
		`				Name:     "logging:cleanup",`,
		`				Interval: 24 * time.Hour,`,
		`				Run: func(ctx context.Context, _ any) error {`,
		`					return jobslogging.Cleanup(ctx, configuration.Core.Logging.Dir)`,
		`				},`,
		`			},`,
		`			{`,
		`				Name:     "backup:daily",`,
		`				Interval: 24 * time.Hour,`,
		`				Run: func(ctx context.Context, _ any) error {`,
		`					return backup.Run(ctx, appDatabase, workerDatabase, dataDir, backupDir, backup.SuffixDaily)`,
		`				},`,
		`			},`,
		`			{`,
		`				Name:     "backup:weekly",`,
		`				Interval: 7 * 24 * time.Hour,`,
		`				Run: func(ctx context.Context, _ any) error {`,
		`					return backup.Run(ctx, appDatabase, workerDatabase, dataDir, backupDir, backup.SuffixWeekly)`,
		`				},`,
		`			},`,
		`			{`,
		`				Name:     "backup:cleanup",`,
		`				Interval: 24 * time.Hour,`,
		`				Run: func(ctx context.Context, _ any) error {`,
		`					return backup.Cleanup(ctx, backupDir)`,
		`				},`,
		`			},`,
	})
}

func joinSectionLines(lines []string) string {
	if len(lines) == 0 {
		return ""
	}

	return strings.Join(lines, "\n") + "\n"
}
